prompt:
You are an expert mathematician. Your task is to provide a thorough and correct proof for a mathematical problem (your Target Problem). This proof will be used to benchmark your abilities as a mathematician.

To obtain your proof, you can assume and use any reference (lemma, theorem, definition, etc) from the context below:

********** BEGIN CONTEXT **********

Tildes on big-O notation suppress polylogarithmic factors, e.g., $\Ot(f) \coloneqq \O(f \polylog(f))$.

\begin{definition}
    An $n$-qubit \emph{Hamiltonian} is a Hermitian $2^n \times 2^n$ matrix
    \begin{equation}
        H = \sum_{a=1}^{4^n} \lambda_a E_a,
    \end{equation}
    where $E_a \in \Pauli{n} = \{\I, X, Y, Z\}^{\otimes n}$ are the unique \emph{Pauli terms} of $H$, and $\lambda_a \in \R$ are the \emph{parameters} of $H$. The labeling $a \in [4^n]$ is arbitrary;~defining the \emph{Pauli structure} of $H$ as the set $S = \{(E_a, \lambda_a) : E_a \neq \I \text{ and } \lambda_a \neq 0\}$, we take convention that the labels $a = 1, \ldots, |S|$ correspond to the elements of $S$. As a slight abuse of notation, we refer to $\lambda \in \R^{|S|}$ as the vector of nonzero parameters, which we can pad with zeros as necessary.
\end{definition}

\begin{definition}
The \emph{Pauli matrices} are defined as
\begin{equation}
    \I = \begin{pmatrix}
        1 & 0\\
        0 & 1
    \end{pmatrix}, \quad
    X = \begin{pmatrix}
        0 & 1\\
        1 & 0
    \end{pmatrix}, \quad
    Y = \begin{pmatrix}
        0 & -\i\\
        \i & 0
    \end{pmatrix}, \quad
    Z = \begin{pmatrix}
        1 & 0\\
        0 & -1
    \end{pmatrix}.
\end{equation}
The set of $n$-qubit Pauli operators $\Pauli{n} \coloneqq \{\I, X, Y, Z\}^{\otimes n}$ is a complete orthogonal operator basis for $\C^{2^n}$, obeying the trace-orthogonality condition $\tr(P^\dagger Q) = 2^n \delta_{PQ}$ for all $P, Q \in \Pauli{n}$.
\end{definition}

\begin{proposition}[Fourier coefficient identities]
    Let $A = \sum_{P \in \Pauli{n}} x_P P$ be any $2^n \times 2^n$ complex matrix. Parseval's identity states that
    \begin{equation}
        \|x\|_2 = \frac{1}{\sqrt{2^n}} \|A\|_F.
    \end{equation}
    An important related identity is
    \begin{equation}
        \frac{1}{\sqrt{2^n}} \|A\|_F = \| (A \otimes \I_n) \ket{\Omega} \|,
    \end{equation}
    where $\ket{\Omega} = \frac{1}{\sqrt{2^n}} \sum_{b \in \{0, 1\}^n} \ket{b} \ket{b}$. This is a consequence of a more general result,
    \begin{equation}
        \ev{(A \otimes \I_n)}{\Omega} = \frac{1}{2^n} \tr A.
    \end{equation}
\end{proposition}

\begin{definition}
    For any bit string $b \in \{0, 1\}^k$, the $k$-qubit controlled variant of an $n$-qubit unitary operator $U$ is
    \begin{equation}
        \ctrl{b}{U} \coloneqq \op{b}{b} \otimes U + (\I_k - \op{b}{b}) \otimes \I_n.
    \end{equation}
    When it is unimportant to specify the control bits $b$, or it is otherwise clear from context, we will simply write $\ctrl{}{U}$.
\end{definition}

\begin{definition}[{\cite[Definition 43]{gilyen2019quantum}}]
    Let $A$ be an $n$-qubit operator and $\alpha, \varepsilon \geq 0$. An $(n + a)$-qubit unitary operator $B$ is called an $(\alpha, a, \varepsilon)$-\emph{block encoding} of $A$ if
    \begin{equation}
        \| A - \alpha (\bra{0^a} \otimes \I_n) B (\ket{0^a} \otimes \I_n) \| \leq \varepsilon.
    \end{equation}
\end{definition}

For brevity, we will use the shorthand:~$(\alpha, a, \varepsilon)$-BE.

\begin{definition}
    Let $H$ be an $n$-qubit Hamiltonian. The \emph{pseudo-Choi state of $H$ with reference} is the $(2n + 1)$-qubit state
    \begin{equation}
        \ket{\pchoiref(H)} \coloneqq \frac{(H \otimes \I_n) \ket{\Omega} \ket{0} + \ket{\Omega} \ket{1}}{\norm(H)},
    \end{equation}
    where $\ket{\Omega} = \frac{1}{\sqrt{2^n}} \sum_{b \in \{0, 1\}^n} \ket{b} \ket{b}$ and $\norm(H) = \sqrt{\frac{1}{2^n} \|H\|_F^2 + 1}$ is a normalization factor.
\end{definition}

\begin{proposition}[{\cite[Lemma 19]{castaneda2023hamiltonian}}]\label{prop:CW_pchoi_prep}
    Let $H$ be an $n$-qubit Hamiltonian and $\Delta \geq 2\|H\|$. Let $\varepsilon \in (0, \frac{\pi}{4}]$. With success probability at least $\frac{1}{2}$, we can prepare a copy of $\ket{\pchoiref(\frac{\widetilde{H}}{\Delta\pi/2})}$, where $\widetilde{H}$ is a Hermitian matrix obeying
    \begin{equation}
        \|H - \widetilde{H}\| \leq \varepsilon \Delta.
    \end{equation}
    This procedure uses $\O(\log(1/\varepsilon))$ queries to $U = e^{-\i H/\Delta}$, its inverse, and their controlled forms.
\end{proposition}

\begin{proposition}\label{prop:prob_state_prep}
    Let $Q \geq N \geq 1$ be integers. Let $\ket{\psi}$ be a state which is probabilistically prepared from a block encoding $B$, with success probability $p \in (0, 1]$. With high probability, we can prepare $N$ copies of $\ket{\psi}$ from
    \begin{equation}
        Q = \Theta(N/p)
    \end{equation}
    queries to $B$.
\end{proposition}

\begin{proposition}[{\cite[Theorem 26, modified for $\ell_\infty$-error]{castaneda2023hamiltonian}}]\label{prop:CW_learning_algorithm}
    Let $H = \sum_{a=1}^m \lambda_a E_a$ be an unknown Hamiltonian and let $\Delta \geq 2 \|H\|$. Assuming access to $U(t) = e^{-\i H t}$, $U(t)^\dagger = U(-t)$, and their multi-controlled forms, there exists an algorithm which can learn each $\lambda_a$ to additive error $\epsilon$. The total number of queries to the time evolution operator is $\Ot(\Delta^2/\epsilon^2)$, the total evolution time is $\Ot(\Delta/\epsilon^2)$, and the minimum time resolution is $\Omega(1/\Delta)$. The amount of classical and quantum computation scales at most polynomially in all parameters.
\end{proposition}

\begin{definition}
    Let $H$ be an $n$-qubit Hamiltonian. The \emph{referenceless pseudo-Choi state of $H$} is the $2n$-qubit state
    \begin{equation}
        \ket{\pchoi(H)} \coloneqq \frac{(H \otimes \I_n) \ket{\Omega}}{\|(H \otimes \I_n) \ket{\Omega}\|},
    \end{equation}
    where $\ket{\Omega} = \frac{1}{\sqrt{2^n}} \sum_{b \in \{0, 1\}^n} \ket{b} \ket{b}$ and $\|(H \otimes \I_n) \ket{\Omega}\| = \frac{1}{\sqrt{2^n}} \|H\|_F$.
\end{definition}

For some $\gamma \in (0, 1)$, define the set
\begin{equation}
    S_\gamma(\widetilde{H}) \coloneqq \{ E_a : |\widetilde{\lambda}_a| > \gamma \}.
\end{equation}

\begin{lemma}\label{lem:coupon_collector}
    Let $\gamma, \delta \in (0, 1)$. Let $\widetilde{H}$ be a Hamiltonian and suppose we have access to copies of its referenceless pseudo-Choi state. With probability at least $1 - \delta$, taking $\O(\|\widetilde{\lambda}\|^2 \log(|S_\gamma(\widetilde{H})|/\delta) / \gamma^2)$ Bell measurements of $\ket{\pchoi(\widetilde{H})}$ suffices to observe all elements of $S_\gamma(\widetilde{H})$.
\end{lemma}

\begin{lemma}\label{lem:big_set_conversion}
    Let $\varepsilon, \epsilon \in (0, 1)$. Let $H, \widetilde{H}$ be two Hamiltonians such that
    \begin{align}
        H &= \sum_{a=1}^m \lambda_a E_a,\\
        \widetilde{H} &= \sum_{a=1}^m \widetilde{\lambda}_a E_a + \sum_{a'=m+1}^{m'} \widetilde{\lambda}_{a'} E_{a'},
    \end{align}
    where $m' \geq m$. Suppose $\|H - \widetilde{H}\| \leq \varepsilon$. Then $S_\epsilon(H) \subseteq S_{\epsilon + \varepsilon}(\widetilde{H})$, and furthermore, $E_{a'} \notin S_{\epsilon + \varepsilon}(\widetilde{H})$ for all $a' = m + 1, m + 2, \ldots, m'$.
\end{lemma}

\begin{theorem}\label{thm:amp_residual_learning}
    Let $H = \sum_{a=1}^m \lambda_a E_a$ be an unknown $n$-qubit Hamiltonian and $\widehat{H} = \sum_{a=1}^m \widehat{\lambda}_a E_a$ an estimate such that $\|\lambda - \widehat{\lambda}\|_\infty \leq \eta$ for some $\eta \in (0, 1]$. There exists a learning algorithm which, with high probability, produces an estimate $\widehat{r}_a'$ of $(\lambda_a - \widehat{\lambda}_a)/\eta$ up to constant additive error (say, $\epsilon_0 = \frac{1}{2}$) for each $a \in [m]$. The algorithm makes $\Ot(m^2/\eta)$ queries to \emph{$\ctrl{}{e^{\pm\i H/(2m)}}$} and uses $\poly(n, m, 1/\eta)$ quantum and classical computation.
\end{theorem}

\begin{theorem}\label{thm:amp_residual_structure}
    Let $H = \sum_{a=1}^m \lambda_a E_a$ be an unknown $n$-qubit Hamiltonian and $\widehat{H} = \sum_{a=1}^m \widehat{\lambda}_a E_a$ an estimate such that $\|\lambda - \widehat{\lambda}\|_\infty \leq \eta$ for some $\eta \in (0, 1]$. There exists a quantum algorithm which, with high probability, identifies all $E_a$ such that $|\lambda_a| \geq \eta/2$. The algorithm makes $\Ot(m^2/\eta)$ queries to \emph{$\ctrl{}{e^{\pm\i H/(2m)}}$} and uses $\poly(n, m, 1/\eta)$ quantum and classical computation.
\end{theorem}

\begin{algorithm}
    \caption{\label{alg:DOS_bootstrap}Bootstrapped learning algorithm with Heisenberg-limited scaling.}
    \KwIn{Error parameters $\epsilon, \delta \in (0, 1)$, base learning algorithm $\alg$, and black-box access to time evolution under the unknown Hamiltonian $H = \sum_{a=1}^m \lambda_a E_a$.}
    \KwOut{An estimate $\widehat{\lambda}$ such that $\Pr(\|\lambda - \widehat{\lambda}\|_\infty \leq \epsilon) \geq 1 - \delta$.}

    \BlankLine

    Let $\widehat{\lambda}^{(0)} \gets (0, \ldots, 0) \in \R^m$\;
    Let $T \gets \lfloor \log_2(1/\epsilon) \rfloor$\;

    \For{$j = 0, 1, \ldots, T$}{
        Let $\zeta_j \gets \delta / 2^{T+1-j}$\;
        Let $\eta_j \gets 1/2^j$\;
        Let $\widehat{H}_j \gets \sum_{a=1}^m \widehat{\lambda}^{(j)}_a E_a$\;
        Let $R_j \gets H - \widehat{H}_j$\;
        $\widehat{r}^{(j)} \gets \alg(R_j/\eta_j, 1/2, \zeta_j)$\;
        Let $\widehat{\lambda}^{(j+1)} \gets \widehat{\lambda}^{(j)} + \eta_j \widehat{r}^{(j)}$\;
    }
    \Return{$\widehat{\lambda} \gets \widehat{\lambda}^{(T+1)}$}
\end{algorithm}

\begin{proposition}\label{prop:bootstrap}
    Suppose that the base algorithm $\alg(H, \eta, \zeta)$ uses $\O(\tau \log(1/\zeta) / \eta^{\alpha})$ evolution time under $H$, for some $\tau > 0$ and $\alpha > 1$. Furthermore, suppose that $\alg$ has the property that $\alg(sH + H', \eta, \zeta)$ uses evolution time $\O(s\tau \log(1/\zeta) / \eta^{\alpha})$, for any $s > 0$ and any (known) Hermitian operator $H'$. Then, Algorithm~\ref{alg:DOS_bootstrap} returns an $\epsilon$-accurate estimate of the Hamiltonian coefficients with probability at least $1 - \delta$, using total evolution time $\O(\tau \log(1/\delta)/\epsilon)$.
\end{proposition}


********** END CONTEXT **********

********** BEGIN EVALUATION CRITERIA **********

Recall that you can assume and use any of the mathematical statements provided in the context above.

Your proof must be complete and valid. As a guideline, here is a non-exhaustive list of criteria to evaluate your proof. You should use it, together with any additional criteria you can think of, to evaluate any candidate proof before your final response.

Evaluation Criteria:

1. **Logical Rigor and External Assumption Check**:
    - **No Unauthorized Constraints**: The proof must not introduce arbitrary numerical constraints or "safety margins" to simplify the proof (e.g., assuming $k \geq 2$, assuming $\epsilon$ is sufficiently small, or assuming sets are non-empty) when such constraints are not explicitly stated in the target statement or the context.
    - **Strict Lemma Adherence**: Every step must follow strictly from the provided context or standard mathematical knowledge. Applying a theorem without explicitly verifying all its preconditions (as defined in the context) is a failure.
    - **Case Integrity**: If the proof involves case-splitting (e.g., $i^* \leq T$ vs $i^* = T+1$), the proof must address these specific boundaries. Skipping a boundary case or "merging" distinct logical paths via hand-waving results in a failure.

2. **Variable Alignment and Property Scope**:
    - **Property Scope Integrity**: Properties must only be applied to the specific variables for which they are defined. If the proof generalizes a property of a subset to a larger set then this constitutes a failure (e.g., applying a $u$-uniformity property defined for "outer queries" $T_2$ to the "total queries" $T$, or applying a property of a specific index $j$ to all indices $i$ without proof).
    - **Index and Set Precision**: The proof must maintain the integrity of sets (e.g., $B$ vs $B^*$, $S_i$ vs $S_{{i-1}}$) and indices. Misidentifying a variable or applying a property to the wrong time step or set is a fatal error.

3. **Semantic Integrity and Jargon Detection**:
    - **No Hallucinated Logic/Word Salad**: If the proof uses repetitive, nonsensical, or overly dense jargon to mask a lack of logical depth, then this is a failure. The proof must be linguistically coherent. If a paragraph consists of technical terms strung together without clear propositional logic (e.g., "mapping limits matching identical parameters constraints mapping"), it is a failure.
    - **No "Standard" Hand-waving**: The proof cannot skip non-trivial derivations by claiming they are "standard", "trivial", etc.

4. **Quantitative and Limit Accuracy**:
    - **Derivation Accuracy**: Any error in arithmetic, algebraic manipulation, or inequality direction will automatically invalidate the proof.
    - **Boundary and Floor/Ceiling Precision**: Bounds must be exactly supported. For example, if a floor function $\lfloor k^{{-\epsilon}} \rfloor$ is used, the proof must account for all valid values of $k$ (including $k=1$) unless the prompt restricts them. Failure to do so, invalidates the proof.

5. **Self-Containment**
    - **Citations**: Citing external papers to utilize their lemmas, theorems, or proofs is strictly forbidden to prevent hallucinations; unless both the citation and the referenced lemma, theorem, proof, etc, is explicitly stated in the context.

6. **Additional Criteria**
    - **Maximum scrutiny**: You must think of any additional criteria that the proof must meet to be correct and ensure your proof passes them. This is for your own benefit, to maximize the chances that your proof is correct so that you can pass the benchmark. You have no incentive to avoid thinking of additional criteria because then you may miss a bug in the proof and fail the benchmark.

********** END EVALUATION CRITERIA **********

********** BEGIN FINAL RESPONSE FORMAT **********

Once you have completed your reasoning, have obtained a proof that passes all evaluation criteria, and are ready to submit your final answer, your final output should be the proof in latex format.

  - DO NOT include any other text, reasoning, or formatting in your final submission turn.
  - If you have the ability to store your answer in a file, DO NOT use it. The proof should be in your final response.

********** END FINAL RESPONSE FORMAT **********

With this in mind, you are tasked to prove the following target statement.

Target Problem (your task):

\begin{theorem}
    Let $H = \sum_{a=1}^m \lambda_a E_a$ be an unknown $n$-qubit Hamiltonian but $m$ given to us. Let $\epsilon, \delta \in (0, 1)$. There exists a structure learning algorithm that outputs $\widehat{\lambda} \in \R^m$, along with classical representations of corresponding $E_1, \ldots, E_m$, such that $\Pr(\|\lambda - \widehat{\lambda}\|_\infty \leq \epsilon) \geq 1 - \delta$. The algorithm uses a total evolution time of $\ttotal = \Ot(m\log(1/\epsilon)/\epsilon)$ to time-forward and time-reverse queries, and uses $\poly(n, m, 1/\epsilon, \log(1/\delta))$ quantum and classical computation.
\end{theorem}

ground_truth_solution:
We start by proving the following 2 auxiliary statements:

\begin{lemma}\label{lem:refless_pchoi_prep}
    Let $H = \sum_{a=1}^m \lambda_a E_a$ be an $n$-qubit Hamiltonian, $\Delta \geq 2 \|H\|$, and $\varepsilon > 0$. With success probability $\Theta(\|\widetilde{\lambda}/\Delta\|^2)$, we can prepare a copy of $\ket{\pchoi(\widetilde{H})}$, where $\widetilde{H}$ is a Hermitian matrix obeying
    \begin{equation}
        \|H - \widetilde{H}\| \leq \varepsilon
    \end{equation}
    and $\widetilde{\lambda}_a = \frac{1}{2^n} \tr(E_a \widetilde{H})$. This procedure uses $\O(\log(\Delta/\varepsilon))$ queries to $U = e^{-\i H/\Delta}$, its inverse, and their controlled forms.
\end{lemma}
\begin{proof}
    The preparation of this state is similar to that of the variant with reference, see \cref{prop:CW_pchoi_prep}. The main difference here is that we do not need a controlled form of the block encoding. Let $B$ be the $(\frac{\pi}{2}, 2, 0)$-BE of $\widetilde{H}/\Delta$ produced from $\O(\log(\Delta/\varepsilon))$ queries, where $\|H - \widetilde{H}\| \leq \varepsilon$. Applying $B \otimes \I_n$ to $\ket{00}\ket{\Omega}$ and measuring the first two qubits, if we obtain $\ket{00}$ in that register then we have successfully prepared $\ket{\pchoi(\widetilde{H})}$ in the remaining $2n$ qubits. This occurs with probability
    \begin{equation}
    \begin{split}
        \Pr(00) &= \l\| \l(\frac{\widetilde{H}}{\Delta \pi/2} \otimes \I_n\r) \ket{\Omega} \r{\|^2}\\
        &= \l( \frac{2}{\pi} \r{)^2} \frac{\|\widetilde{H}/\Delta\|^2_F}{2^n}\\
        &= \l( \frac{2}{\pi} \r{)^2} \| \widetilde{\lambda}/\Delta \|^2.
    \end{split}
    \end{equation}
    \end{proof}

\begin{theorem}\label{thm:structure_learning_base}
    Let $H = \sum_{a=1}^m \lambda_a E_a$ be an unknown $n$-qubit Hamiltonian, $\Delta \geq 2 \|H\|$, and $\epsilon > 0$. Define the set $S_\epsilon(H) = \{E_a : |\lambda_a| > \epsilon\}$. There exists an algorithm which learns, with high probability, at least all the elements of $S_\epsilon(H)$. The algorithm makes
    \begin{equation}
        Q = \O\l( \frac{\Delta^2 \log(m) \log(\Delta/\epsilon)}{\epsilon^2} \r).
    \end{equation}
    queries to \emph{$\ctrl{}{e^{\pm \i H/\Delta}}$} and uses $\poly(n, m, 1/\epsilon)$ quantum and classical computation.
\end{theorem}
\begin{proof}
    \cref{lem:coupon_collector} tell us that, with high probability,
    \begin{equation}
        N = \O\l(\frac{\|\widetilde{\lambda}\|^2 \log |S_\gamma(\widetilde{H})|}{\gamma^2}\r)
    \end{equation}
    copies of $\ket{\pchoi(\widetilde{H})}$ suffice to learn $S_\gamma(\widetilde{H})$ via Bell measurements. Meanwhile, \cref{lem:refless_pchoi_prep} tells us that the probability of successfully generating a single copy is
    \begin{equation}
        p = \Theta\l(\frac{\|\widetilde{\lambda}\|^2}{\Delta^2}\r).
    \end{equation}
    By \cref{prop:prob_state_prep}, we need to take $Q' = \O(N/p)$ trials to produce the $N$ copies. Therefore from
    \begin{equation}
        Q' = \O\l(\frac{\Delta^2 \log |S_\gamma(\widetilde{H})|}{\gamma^2}\r)
    \end{equation}
    queries to the block encoding of $\widetilde{H}/\Delta$, or equivalently $Q = \O(Q' \log(\Delta/\varepsilon))$ queries to the time evolution operator, we learn the set $S_\gamma(\widetilde{H})$ with high probability. Finally by \cref{lem:big_set_conversion}, setting $\gamma = \epsilon + \varepsilon$ ensures that the set $S_{\epsilon + \varepsilon}(\widetilde{H})$ that we have learned contains $S_\epsilon(H)$ as a subset. \cref{lem:big_set_conversion} also assures us that $|S_{\epsilon + \varepsilon}(\widetilde{H})| \leq m$ since it cannot contain any superfluous terms. Taking $\varepsilon = \Theta(\epsilon)$ sufficiently small concludes the proof.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
    We combine \cref{thm:amp_residual_learning,thm:amp_residual_structure} to construct the base algorithm $\alg$. (For the $j = 0$ step, we can use \cref{prop:CW_learning_algorithm,thm:structure_learning_base} without using uniform spectral amplification, at the cost of slightly worse constant factors.) Let $R_j = H - \widehat{H}_j$, $\eta_j = 2^{-j}$, and $\zeta_j = \delta/2^{T+1-j}$. We first identify the terms in $R_j/\eta_j$ which are at least $1/2$ in magnitude, $\widehat{S}_j \supseteq S_{1/2}(R_j/\eta_j)$. By \cref{thm:amp_residual_structure}, this costs $\Ot(m^2 \log(1/\eta_j)/\eta_j)$ queries evolving for time $\frac{1}{2m}$. Then we estimate all $\widehat{r}_j$ corresponding to the Pauli terms in $\widehat{S}_j$, which by \cref{thm:amp_residual_learning} has the same query complexity. Repeating these procedures $\O(\log(1/\zeta_j))$ times and taking the median for each estimate suppresses the failure probability to at most $\zeta_j$.

    Thus, $\alg(R_j/\eta_j, 1/2, \zeta_j)$ uses evolution time
    \begin{equation}
        |t_j| = \Ot((m\log(1/\eta_j)/\eta_j) \log(1/\zeta_j)) \leq \Ot((m\log(1/\epsilon)/\eta_j) \log(1/\zeta_j)),
    \end{equation}
    where the $\Ot(\cdot)$ notation here suppresses logarithmic factors not involving $\eta_j$, $\zeta_j$, $\epsilon$, or $\delta$. Inserting this into the result of \cref{prop:bootstrap} with $\tau = m \log(1/\epsilon)$ yields the claim.
\end{proof}
